CREATE TABLE fixture_provenance (producer TEXT NOT NULL);
CREATE TABLE fixture_metrics (name TEXT PRIMARY KEY, value INTEGER NOT NULL);
CREATE TABLE events (seq INTEGER PRIMARY KEY AUTOINCREMENT, event_id TEXT NOT NULL, tenant_id TEXT NOT NULL DEFAULT 'local', kind TEXT NOT NULL, aggregate_id TEXT, aggregate_seq INTEGER, owner_id TEXT, session_id TEXT, event_json TEXT NOT NULL, created INTEGER NOT NULL);
INSERT INTO fixture_provenance VALUES ('official-crates.io-turso-0.6.1');
CREATE TABLE sessions (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL DEFAULT 'local', info_json TEXT NOT NULL, updated INTEGER NOT NULL);
CREATE TABLE messages (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL DEFAULT 'local', session_id TEXT NOT NULL, message_json TEXT NOT NULL, created INTEGER NOT NULL, position INTEGER NOT NULL DEFAULT 0);
INSERT INTO sessions VALUES ('ses_fixture', 'local', '{ "id":"ses_fixture", "slug":"fixture", "projectId":"global", "directory":"/fixture", "title":"Fixture", "version":"test", "time":{"created":1,"updated":1}, "opaque":{"spaces":"  untouched  ","unicode":"雪"} }', 1);
