CREATE TABLE data_migrations (name TEXT PRIMARY KEY, state TEXT NOT NULL, cursor_updated INTEGER, cursor_id TEXT, rows_done INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL, error TEXT);
INSERT INTO data_migrations VALUES ('conversation-search-sessions-v1', 'complete', 123, 'ses_fixture', 17, 41, NULL);
