CREATE TABLE conversation_search_docs (key TEXT PRIMARY KEY, session_id TEXT NOT NULL, message_id TEXT NOT NULL, role TEXT NOT NULL, created INTEGER NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL);
CREATE INDEX conversation_search_session ON conversation_search_docs(session_id);
CREATE TABLE conversation_search_dirty (key TEXT PRIMARY KEY, session_id TEXT NOT NULL, message_id TEXT NOT NULL, revision TEXT NOT NULL, ready_at INTEGER NOT NULL);
CREATE INDEX conversation_search_ready ON conversation_search_dirty(ready_at, key);
CREATE INDEX conversation_search_dirty_session ON conversation_search_dirty(session_id);
INSERT INTO conversation_search_dirty VALUES ('message:msg_pending', 'ses_fixture', 'msg_pending', 'preserve-revision', 9999999999999);
CREATE INDEX conversation_search_fts ON conversation_search_docs USING fts (title, body) WITH (weights='title=3.0,body=1.0');
